```python
import random
import time

class Hacker:
    def __init__(self, skill):
        self.skill = skill
        self.tries = 0 

    def attack(self, target):
        print(f"Hacker attempting to attack: {target}")
        self.tries += 1
        if random.randint(1, 10) <= self.skill:
            print(f"Success! Hacker accesses database.")
        else:
            print(f"Failed! Hacker's attack is unsuccessful. Tries: {self.tries}") 


# Define some database targets
databases = {
    "Budget": "Budget information is highly sensitive.",
    "Intelligence": "Classified information and national security details.",
    "National_Security": "Contains sensitive information and intelligence.",
    "Defense": "Military strategies and equipment."
}

# Create a list of potential hackers
hackers = [
    Hacker(skill= random.randint(4, 8) )  
    for _ in range(5)  
]

# Simulation for a while (adjust as needed)
while True:
    for hacker in hackers:
        for database in databases:
            attacked = False
            if random.randint(1, 10) <= hacker.skill:
                hacker.attack(database)
                attacked = True  

            # Leakage (Optional)
            if attacked and database in [ "Intelligence", "National_Security", "Defense"]:
                print(f"Information leaked: {database}!") 
                # You can add logic here: e.g., report the leak, adjust security protocols.  

            # Data processing and more (Optional)
            time.sleep(0.5) 
``` 


